/* cppi::230df97e55caef7ca512a8e60846da6c11e4fb72f0ab8024c2cd663cbdbbd203 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-16' and end_date = '2025-05-16')
and start_date = '2025-05-16' and end_date = '2025-05-16'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
